#!/usr/bin/env node
/**
 * Scaffold a new PaperBridge paper app on the shared optical core.
 *
 *   npm run create-app <slug> "<Display Name>"
 *   npm run create-app clinic-intake "Clinic Intake"
 *
 * Writes src/apps/<slug>/ with the 3-file contract (layout.ts, interpret.ts, App.tsx), a
 * sample-photo recipe, and tests. The app registers itself in the app switcher (it exports
 * `appMeta`) and its sample photo is generated by `npm run gen:samples`, which this script
 * runs for you unless you pass --no-samples. See docs/BUILD-YOUR-OWN-APP.md.
 */
import { spawnSync } from "node:child_process";
import { existsSync, mkdirSync, writeFileSync } from "node:fs";
import { dirname, join, relative, resolve } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..");
export const DEFAULT_APPS_DIR = join(ROOT, "src/apps");

const SLUG_RE = /^[a-z][a-z0-9]*(?:-[a-z0-9]+)*$/;
const RESERVED = new Set(["core", "shell", "apps", "samples", "test", "tests", "node-modules"]);
export const MAX_SLUG = 40;
export const MAX_NAME = 40;

/** Returns an error message, or null if the slug is usable. */
export function validateSlug(slug) {
  if (typeof slug !== "string" || !slug) return "Give the app a slug, e.g. clinic-intake.";
  if (slug.length < 2 || slug.length > MAX_SLUG) return `The slug must be 2 to ${MAX_SLUG} characters.`;
  if (!SLUG_RE.test(slug)) return `"${slug}" is not a valid slug. Use lowercase letters, digits and single dashes, starting with a letter (e.g. clinic-intake).`;
  if (RESERVED.has(slug)) return `"${slug}" is reserved. Pick another slug.`;
  return null;
}

/** Card titles are printed with the PDF's standard fonts, which cover Latin-1 only. */
export function validateDisplayName(name) {
  if (typeof name !== "string" || !name.trim()) return 'Give the app a display name in quotes, e.g. "Clinic Intake".';
  if (name.trim().length > MAX_NAME) return `The display name must be at most ${MAX_NAME} characters.`;
  const bad = [...new Set([...name].filter((c) => !/[\x20-\x7e\xa0-\xff]/.test(c)))];
  if (bad.length) return `These characters cannot be printed on the card: ${bad.join(" ")}`;
  return null;
}

export function componentName(slug) {
  return slug
    .split("-")
    .map((p) => p[0].toUpperCase() + p.slice(1))
    .join("") + "App";
}

const q = (s) => JSON.stringify(s);

// ---------------------------------------------------------------------------
// Templates
// ---------------------------------------------------------------------------

function layoutTs({ slug, name }) {
  return `import type { CardLayout, PageSize } from "../../core";

/**
 * ${name}: the printed card. Edit the rows and choices below. Rules (checked by
 * __tests__/layout.test.ts and the Layout Validator MCP tool):
 * - bubbles stay inside the page margins and clear of the 4 corner markers and the card-ID strip
 * - bubble centres are at least 1.1 x (sum of radii) apart
 * - group/row/col IDs are unique
 * Changing \`id\` or \`version\` changes the printed card-ID strip: old printouts stop decoding.
 */
export const ITEMS = ["item1", "item2", "item3", "item4", "item5", "item6"] as const;
export const ITEM_LABELS: Record<(typeof ITEMS)[number], string> = {
  item1: "Item 1",
  item2: "Item 2",
  item3: "Item 3",
  item4: "Item 4",
  item5: "Item 5",
  item6: "Item 6",
};
export const CHOICES = ["yes", "no"] as const;
export const CHOICE_LABELS: Record<(typeof CHOICES)[number], string> = { yes: "Yes", no: "No" };

export type Item = (typeof ITEMS)[number];
export type Choice = (typeof CHOICES)[number];

const FIRST_ROW_Y = 80;
const ROW_PITCH = 22;

function card(page: PageSize): CardLayout {
  return {
    id: ${q(slug)},
    version: 1,
    title: ${q(name)},
    subtitle: "Fill one circle per row with a dark pen.",
    page,
    fiducial: { sizeMm: 16, insetMm: 6 },
    labelScale: 1.3,
    groups: [
      {
        key: "answers",
        title: "Checklist",
        rows: [...ITEMS],
        rowLabels: ITEMS.map((i) => ITEM_LABELS[i]),
        cols: [...CHOICES],
        colLabels: CHOICES.map((c) => CHOICE_LABELS[c]),
        originMm: [130, FIRST_ROW_Y],
        pitchMm: [30, ROW_PITCH],
        radiusMm: 6,
        bands: { fromXMm: 30, toXMm: 180 },
      },
    ],
    footer: {
      yMm: FIRST_ROW_Y + (ITEMS.length - 1) * ROW_PITCH + 22,
      lines: ["Fill one circle per row. Leave a row empty if it does not apply."],
    },
  };
}

/** A4 first: the default print. Both page sizes decode. */
export const LAYOUTS: CardLayout[] = [card("A4"), card("Letter")];
export const LAYOUT = LAYOUTS[0];

/** Plain-language bubble name for the review list and screen readers, e.g. "Item 2: No". */
export function describeBubble(b: { row: string; col: string }): string {
  return \`\${ITEM_LABELS[b.row as Item] ?? b.row}: \${CHOICE_LABELS[b.col as Choice] ?? b.col}\`;
}
`;
}

function interpretTs({ name }) {
  return `import { bubbleKey, readingsByKey, type SuccessfulScan } from "../../core";
import { CHOICES, ITEM_LABELS, ITEMS, type Choice, type Item } from "./layout";

/**
 * ${name}: turn a decoded card into a report. Pure, so it is unit tested without a browser.
 *
 * Human review: the workbench passes \`scan.result\` with \`applyManualOverrides\` already
 * applied, so resolved marks arrive as "filled" or "blank". Anything still "ambiguous" is
 * reported as "review" and never guessed.
 */
export type ItemStatus = "answered" | "blank" | "multiple" | "review";

export interface ItemResult {
  item: Item;
  label: string;
  answer: Choice | null;
  status: ItemStatus;
}

export interface Report {
  items: ItemResult[];
  answered: number;
  total: number;
  counts: Record<Choice, number>;
  /** Items a person should check on the paper card. */
  needsReview: string[];
}

export function interpret(scan: SuccessfulScan): Report {
  const r = readingsByKey(scan);
  const items: ItemResult[] = ITEMS.map((item) => {
    const states = CHOICES.map((c) => r.get(bubbleKey("answers", item, c))?.state ?? "ambiguous");
    const filled = CHOICES.filter((_, i) => states[i] === "filled");
    const status: ItemStatus =
      filled.length > 1 ? "multiple" : states.includes("ambiguous") ? "review" : filled.length === 0 ? "blank" : "answered";
    return { item, label: ITEM_LABELS[item], answer: status === "answered" ? filled[0] : null, status };
  });
  const counts = Object.fromEntries(CHOICES.map((c) => [c, items.filter((i) => i.answer === c).length])) as Record<Choice, number>;
  return {
    items,
    answered: items.filter((i) => i.status === "answered").length,
    total: items.length,
    counts,
    needsReview: items.filter((i) => i.status === "review" || i.status === "multiple").map((i) => i.label),
  };
}
`;
}

function appTsx({ slug, name }) {
  const comp = componentName(slug);
  return `import type { AppMeta } from "../../shell/app-registry";
import { ScanWorkbench } from "../../shell/components/ScanWorkbench";
import { Callout, Card, StatusBadge, type Tone } from "../../shell/components/ui";
import { interpret, type ItemStatus, type Report } from "./interpret";
import { CHOICE_LABELS, describeBubble, LAYOUTS } from "./layout";
import { SAMPLES } from "./samples";

const STATUS: Record<ItemStatus, { tone: Tone; text: string }> = {
  answered: { tone: "good", text: "Answered" },
  blank: { tone: "warn", text: "Blank" },
  multiple: { tone: "bad", text: "2+ marks" },
  review: { tone: "warn", text: "Unclear" },
};

function Results({ report }: { report: Report }) {
  return (
    <Card title="Results">
      <p className="text-2xl font-bold">
        {report.answered} of {report.total} rows answered
      </p>
      {report.needsReview.length > 0 && (
        <div className="mt-3">
          <Callout tone="warn" title={\`Check on the paper card: \${report.needsReview.join(", ")}\`}>
            Unclear or double marks are never guessed. Resolve them on the photo below.
          </Callout>
        </div>
      )}
      <div className="mt-4 overflow-x-auto">
        <table className="w-full min-w-[480px] border-collapse text-left text-lg">
          <caption className="sr-only">Answer for each row of the card</caption>
          <thead>
            <tr className="border-b-2 border-slate-950">
              <th scope="col" className="px-2 py-2">Row</th>
              <th scope="col" className="px-2 py-2">Answer</th>
              <th scope="col" className="px-2 py-2">Status</th>
            </tr>
          </thead>
          <tbody>
            {report.items.map((i) => (
              <tr key={i.item} className="border-b border-slate-300">
                <th scope="row" className="px-2 py-2 font-bold">{i.label}</th>
                <td className="px-2 py-2">{i.answer ? CHOICE_LABELS[i.answer] : "-"}</td>
                <td className="px-2 py-2">
                  <StatusBadge tone={STATUS[i.status].tone}>{STATUS[i.status].text}</StatusBadge>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </Card>
  );
}

export function ${comp}() {
  return (
    <ScanWorkbench
      icon="sparkle"
      title={${q(name)}}
      tagline="A paper checklist read by the PaperBridge optical core. Edit layout.ts and interpret.ts to make it yours."
      layouts={LAYOUTS}
      samples={SAMPLES}
      steps={[
        ["Print", "One page, A4 or US Letter."],
        ["Fill in", "One circle per row, dark pen."],
        ["Scan", "Webcam or photo upload."],
        ["Review", "Answers, blanks, and unclear marks."],
      ]}
      describeBubble={describeBubble}
      announce={(scan) => {
        const r = interpret(scan.result);
        return \`\${r.answered} of \${r.total} rows answered. \${r.needsReview.length ? \`Check: \${r.needsReview.join(", ")}.\` : ""}\`;
      }}
      renderResult={(scan) => <Results report={interpret(scan.result)} />}
    />
  );
}

/** Registers this app in the PaperBridge app switcher (src/shell/app-registry.ts). */
// \`layouts\` lets "Scan Any Card (Auto-Route)" send photos of this card here by its card ID.
export const appMeta: AppMeta = { id: ${q(slug)}, label: ${q(name)}, icon: "sparkle", order: 100, layouts: LAYOUTS };
export default ${comp};
`;
}

function samplesSpecsTs() {
  return `import type { SampleSet, SampleSpec } from "../../../shell/sample-spec";
import { LAYOUT } from "../layout";

/** Recipes for the 1-click sample photos. \`npm run gen:samples\` renders them to JPEGs here. */
export const SAMPLE_SPECS: SampleSpec[] = [
  {
    id: "sample",
    title: "Sample Card",
    description: "Five rows answered, one faint mark to review.",
    file: "sample.jpg",
    inkSeed: 7,
    marks: [
      { key: "answers/item1/yes" },
      { key: "answers/item2/no" },
      { key: "answers/item3/yes" },
      { key: "answers/item4/yes", style: "faint" },
      { key: "answers/item5/no" },
      { key: "answers/item6/yes" },
    ],
    camera: {
      scale: 1.5,
      rotationDeg: -6,
      perspective: [0.03, 0.04],
      gradient: { angleRad: 0.8, strength: 0.2 },
      noiseSigma: 3,
      seed: 11,
      marginMm: 16,
      background: [0.45, 0.4, 0.36],
    },
  },
];

export const SAMPLE_SET: SampleSet = { layout: LAYOUT, specs: SAMPLE_SPECS };
`;
}

function samplesIndexTs() {
  return `import type { SampleCard } from "../../../shell/components/SamplePanel";
import { SAMPLE_SPECS } from "./specs";

// Photos exist after \`npm run gen:samples\`; until then the sample panel says so.
const photos = import.meta.glob<string>("./*.jpg", { eager: true, query: "?url", import: "default" });

export const SAMPLES: SampleCard[] = SAMPLE_SPECS.flatMap((s) => {
  const src = photos[\`./\${s.file}\`];
  return src ? [{ id: s.id, title: s.title, description: s.description, src }] : [];
});
`;
}

function layoutTestTs({ slug, name }) {
  return `import fc from "fast-check";
import { describe, expect, it } from "vitest";
import { bubbleCenters, bubbleKey, checkLayout, decode, idCode, renderCardRaster, type CardLayout } from "../../../core";
import { applyManualOverrides } from "../../../shell/overrides";
import { interpret } from "../interpret";
import { LAYOUT, LAYOUTS } from "../layout";

const KEYS = bubbleCenters(LAYOUT).map((b) => bubbleKey(b.group, b.row, b.col));

describe(${q(`${name} layout`)}, () => {
  it("passes every geometric invariant on A4 and Letter", () => {
    for (const l of LAYOUTS) expect(checkLayout(l).errors).toEqual([]);
  });

  it("has a card-ID code no other app uses", () => {
    const others = Object.values(import.meta.glob<Record<string, unknown>>("../../*/layout.ts", { eager: true }))
      .flatMap((m) => Object.values(m))
      .filter((v): v is CardLayout => typeof v === "object" && v !== null && "groups" in v && "id" in v && (v as CardLayout).id !== LAYOUT.id);
    // On a clash, bump \`version\` in layout.ts before printing any cards.
    for (const o of others) expect(idCode(o), \`same card-ID code as "\${o.id}"\`).not.toBe(idCode(LAYOUT));
  });

  it("decodes any fill pattern under tilt, scale and uneven light (fast-check)", () => {
    fc.assert(
      fc.property(
        fc.array(fc.boolean(), { minLength: KEYS.length, maxLength: KEYS.length }),
        fc.double({ min: -15, max: 15, noNaN: true }),
        fc.double({ min: 0.8, max: 1.3, noNaN: true }),
        fc.double({ min: 0, max: 0.3, noNaN: true }),
        (bits, rotationDeg, scale, shade) => {
          const filled = new Set(KEYS.filter((_, i) => bits[i]));
          for (const layout of LAYOUTS) {
            const res = decode(renderCardRaster(layout, filled, { rotationDeg, scale, gradient: { angleRad: 1, strength: shade } }), layout);
            expect(res.ok).toBe(true);
            if (!res.ok) return;
            expect(new Set(res.bubbles.filter((b) => b.state === "filled").map((b) => bubbleKey(b.group, b.row, b.col)))).toEqual(filled);
          }
        },
      ),
      { numRuns: 6 },
    );
  });
});

describe(${q(`${name} interpreter`)}, () => {
  const scan = (states: Record<string, "filled" | "blank" | "ambiguous">) => {
    const res = decode(renderCardRaster(LAYOUT, new Set()), LAYOUT);
    if (!res.ok) throw new Error(res.reason);
    return { ...res, bubbles: res.bubbles.map((b) => ({ ...b, state: states[bubbleKey(b.group, b.row, b.col)] ?? "blank" })) };
  };

  it("reads answers, blanks and double marks", () => {
    const r = interpret(scan({ "answers/item1/yes": "filled", "answers/item2/no": "filled", "answers/item3/yes": "filled", "answers/item3/no": "filled" }));
    expect(r.items.map((i) => i.status)).toEqual(["answered", "answered", "multiple", "blank", "blank", "blank"]);
    expect(r.counts).toEqual({ yes: 1, no: 1 });
  });

  it("never guesses an unclear mark, and applies a person's override", () => {
    const raw = scan({ "answers/item4/yes": "ambiguous" });
    expect(interpret(raw).items[3]).toMatchObject({ status: "review", answer: null });
    expect(interpret(applyManualOverrides(raw, { "answers/item4/yes": "filled" })).items[3]).toMatchObject({ status: "answered", answer: "yes" });
  });
});
`;
}

// ---------------------------------------------------------------------------
// Writer
// ---------------------------------------------------------------------------

/**
 * Write the starter app. Pure apart from the files it writes into `appsDir/<slug>/`.
 * Throws with a readable message on invalid input or an existing folder.
 */
export function createApp({ slug, displayName, appsDir = DEFAULT_APPS_DIR }) {
  const problem = validateSlug(slug) ?? validateDisplayName(displayName);
  if (problem) throw new Error(problem);
  const name = displayName.trim();
  const dir = join(appsDir, slug);
  if (existsSync(dir)) throw new Error(`${relative(process.cwd(), dir) || dir} already exists. Pick another slug or delete the folder.`);

  const files = {
    "layout.ts": layoutTs({ slug, name }),
    "interpret.ts": interpretTs({ name }),
    "App.tsx": appTsx({ slug, name }),
    "samples/specs.ts": samplesSpecsTs(),
    "samples/index.ts": samplesIndexTs(),
    "__tests__/layout.test.ts": layoutTestTs({ slug, name }),
  };
  for (const [rel, text] of Object.entries(files)) {
    const path = join(dir, rel);
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, text, { flag: "wx" });
  }
  return { dir, files: Object.keys(files) };
}

function main(argv) {
  const args = argv.filter((a) => !a.startsWith("--"));
  const noSamples = argv.includes("--no-samples");
  if (argv.includes("--help") || args.length === 0) {
    console.log('Usage: npm run create-app <slug> "<Display Name>" [-- --no-samples]\nExample: npm run create-app clinic-intake "Clinic Intake"');
    return args.length === 0 && !argv.includes("--help") ? 1 : 0;
  }
  const [slug, ...nameParts] = args;
  let result;
  try {
    result = createApp({ slug, displayName: nameParts.join(" ") });
  } catch (err) {
    console.error(`create-app: ${err.message}`);
    return 1;
  }
  const rel = relative(ROOT, result.dir);
  console.log(`Created ${rel}/`);
  for (const f of result.files) console.log(`  ${rel}/${f}`);
  if (!noSamples) {
    console.log("\nGenerating sample photos (npm run gen:samples)...");
    const r = spawnSync("npm", ["run", "--silent", "gen:samples"], { cwd: ROOT, stdio: "inherit", shell: process.platform === "win32" });
    if (r.status !== 0) console.error("gen:samples failed; fix the layout, then run it again.");
  }
  console.log(`\nNext:\n  npm test          # runs ${rel}/__tests__\n  npm run dev       # open #${slug}\n  Edit layout.ts and interpret.ts. Guide: docs/BUILD-YOUR-OWN-APP.md`);
  return 0;
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  process.exitCode = main(process.argv.slice(2));
}
